#!/usr/bin/env Rscript
options(warn=2); args<-commandArgs(trailingOnly=TRUE); if(length(args)!=4L) stop("usage: build_mv17b_null_qualification_closure.R <prefreeze> <primary> <repeat> <output>")
p<-normalizePath(args[[1]],mustWork=TRUE); a<-normalizePath(args[[2]],mustWork=TRUE); b<-normalizePath(args[[3]],mustWork=TRUE); o<-args[[4]]; if(dir.exists(o)) stop("MV17-B closure exists"); dir.create(o,recursive=TRUE)
source("R/mv08z_landscape_production.R"); r<-.mv08z_read_csv; w<-.mv08z_atomic_csv; h<-.mv08z_sha256_file
x<-r(file.path(a,"mv17b-qualification.csv")); y<-r(file.path(b,"mv17b-qualification.csv")); s<-r(file.path(a,"mv17b-status.csv")); c<-r(file.path(p,"mv17b-contract.csv"))
v<-data.frame(contract_id="mv17b_closure_validation_v1",check_id=c("36_jobs","all_invariants","all_deterministic","byte_repeat","circle_separation","real_closed","PH_closed"),passed=c(nrow(x)==36L,all(x$passed_invariant),all(x$deterministic),h(file.path(a,"mv17b-qualification.csv"))==h(file.path(b,"mv17b-qualification.csv")),all(x$neighbor_jaccard[x$fixture=="circle_in_3d"]<=c$maximum_circle_neighbor_jaccard),s$real_corpus_jobs==0L,s$PH_jobs==0L)); if(!all(v$passed)) stop("MV17-B closure failed")
w(v,file.path(o,"mv17b-validation.csv")); w(data.frame(contract_id="mv17b_closure_decision_v1",MV17B_closed=TRUE,MV17C_implementation_eligible=TRUE,real_calibration_authorized=FALSE),file.path(o,"mv17b-decision.csv")); files<-sort(list.files(o)); w(data.frame(contract_id="mv17b_closure_manifest_v1",artifact=files,bytes=as.numeric(file.info(file.path(o,files))$size),sha256=vapply(file.path(o,files),h,character(1))),file.path(o,"mv17b-artifact-manifest.csv"))
